import sys
import pytest

class Trace:
    def __init__(self):
        self.counts = {}

    @pytest.hookimpl(hookwrapper=True)
    def pytest_runtest_call(self, item):
        hits = []
        def profile(frame, event, arg):
            if event == 'call' and frame.f_code.co_name == '_setattr' and frame.f_code.co_filename.endswith('/src/attr/_make.py'):
                hits.append((frame.f_locals.get('attr_name'), frame.f_locals.get('value_var')))
        sys.setprofile(profile)
        try:
            yield
        finally:
            sys.setprofile(None)
            self.counts[item.nodeid] = hits

plugin = Trace()
code = pytest.main(['-q', 'tests/test_functional.py::TestFunctional::test_on_setattr_detect_inherited_validators', 'tests/test_setattr.py::TestSetAttr::test_change', 'tests/test_setattr.py::TestSetAttr::test_frozen_attribute'], plugins=[plugin])
for nodeid, hits in plugin.counts.items():
    print(f'TRACE {nodeid}: {len(hits)} calls; args={hits}')
raise SystemExit(code)
